def unit_of_work(metadata=None, timeout=None):
    def decorator(func):
        def wrapper(*args, **kwargs):
            # Execute the decorated function and get the result
            result = func(*args, **kwargs)

            # Get the Neo4j transaction object from the passed arguments
            tx = None
            for arg in args:
                if isinstance(arg, Neo4jTransaction):
                    tx = arg
                    break

            # Set the transaction metadata and timeout if specified in the decorator
            if tx is not None:
                if metadata is not None:
                    tx.set_tx_metadata(metadata)
                if timeout is not None:
                    tx.set_tx_timeout(timeout)

            return result

        return wrapper

    return decorator
