def unit_of_work(func):
    def wrapper(*args, **kwargs):
        metadata = kwargs.get('metadata', {})
        timeout = kwargs.get('timeout', 0)
        func_sig = inspect.getfullargspec(func).args
        if 'timeout' not in func_sig:
            # decorator overrides function signature if `timeout` param is provided
            # if timeoout is not in the original function signature, we raise an error
            raise exceptions.Neo4JTransactionException('Provided `timeout` argument is not compatible with function signature')

        # enforce metadata validation
        if not isinstance(metadata, dict):
            raise exceptions.Neo4JTransactionException('Provided `metadata` argument must be a dictionary')
        metadata.update(kwargs.get('metadata', {}))

        # enforce timeout validation
        if timeout is None:
            # do nothing, let the transaction follow the original timeout setting
            return getattr(func, 'timeout', 0)
        elif not isinstance(timeout, (int, float, np.number)):
            raise exceptions.Neo4JTransactionException('Provided `timeout` argument must be a number')
        elif timeout < 0:
            raise exceptions.Neo4JTransactionException('Provided `timeout` argument must be a positive duration')
        elif timeout == 0:
            timeout = getattr(func, 'timeout', 0)

        # finally, execute the function
        try:
            return func(*args, **kwargs)
        except Exception as e:
            # handle any exceptions raised during execution
            # if there was a timeout, raise a specific Neo4JTransactionTimedOutError
            if hasattr(e, 'neo4j_error'):
                raise exceptions.Neo4JTransactionTimedOutError('Transaction timed out after {timeout} seconds.')
            else:
                raise exceptions.Neo4JTransactionException(e)

    return wrapper
