def _legacy_mergeOrderings(orderings: list[list[T]]) -> list[T]:
    def get_suffix(obj: T, orderings: list[list[T]]) -> bool:
        for ordering in orderings:
            if ordering[-1] == obj:
                return True
        return False

    result: list[T] = []
