def minimalBases(classes):
    ordered_bases = []
    while len(classes) > 0:
        new_base = classes[0]
        for i in range(1, len(classes)):
            if issubclass(new_base, classes[i]):
                new_base = classes[i]
                classes.pop(i)
                break
        ordered_bases.append(new_base)
        classes.remove(new_base)
    return ordered_bases

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    classes = list(classes)
    result = []
    while classes:
        cls = classes.pop(0)
        if cls not in result:
            result.append(cls)
            classes = [c for c in classes if c not in result]

    return result

