import re

def validate(self, inventory, extract_spec_version=False):
    self.check_inventory(inventory)
    if extract_spec_version:
        try:
            spec_version = inventory["project_info"]["type"]
        except KeyError:
            spec_version = self.spec_version
    else:
        spec_version = self.spec_version
    return self.check_spec_version(spec_version)

def check_inventory(self, inventory):
    if not isinstance(inventory, dict):
        raise ValueError("Inventory is not a dictionary")
    if not self.check_type(inventory):
        raise ValueError("Type is not valid")
    if not self.check_name(inventory):
        raise ValueError("Name is not valid")
    return None

def check_type(self, inventory):
    try:
        if not re.match(r"^S_[0-9]+$", inventory["type"]):
            return False
    except KeyError:
        return False
    return True

def check_name(self, inventory):
    try:
        if not re.match(r"^[A-Z][a-z_0-9]+$", inventory["name"]):
            return False
    except KeyError:
        return False
    return True

def check_spec_version(self, spec_version):
    if not isinstance(spec_version, str):
        raise ValueError("Specification version is not a string")
    if not re.match(r"^S_[0-9]+p{0,2}$", spec_version):
        raise ValueError("Specification version is not valid")
    spec_major = int(spec_version.split("S_")[1])
    if spec_major > self.spec_version:
        raise ValueError(f"Specification major version ({spec_major}) is greater than allowed specification version (self.spec_version)")
    return True
