        raise TypeError("prior must be an InventoryValidator object")
    if self.version <= prior.version:
        raise ValueError("prior version must be older than self version")
    # Check that all items in prior are also in self
    for item in prior.items:
        if item not in self.items:
            raise ValueError("prior inventory must contain all items in self inventory")
    # Check that the all item quantities in prior are smaller than or equal to the corresponding quantities in self
    for item, quantity in prior.items.items():
        if self.items[item] < quantity:
            raise ValueError("prior inventory must contain no more than the corresponding quantity of items in self inventory")
    return True

