def validate_fixity(self, fixity, manifest_files):
    if fixity is None:
        raise ValueError("Fixity block cannot be None")

    # Check that all files in manifest are referenced in fixity
    manifest_files = set(manifest_files)
    fixity_files = set(fixity.keys())
    if len(manifest_files - fixity_files) > 0:
        raise ValueError("Fixity block contains files not referenced in manifest")

    # Check that fixity contains the correct structure
    required_keys = ('fund', 'age', 'created_by')
    if not all(key in fixity for key in required_keys):
        raise ValueError("Fixity block must contain the following keys: {}".format(", ".join(required_keys)))

    # Check that all files referenced in fixity have a valid structure
    for file in fixity_files:
        if file not in manifest_files:
            raise ValueError("File '{}' is not referenced in manifest".format(file))
        if not isinstance(fixity[file], dict):
            raise ValueError("File '{}' does not have a valid structure".format(file))
        required_filename_keys = ('algorithm', 'hex', 'size')
        if not all(key in fixity[file] for key in required_filename_keys):
            raise ValueError("File '{}' does not have the following keys: {}".format(file, ", ".join(required_filename_keys)))

    # If all checks pass, return fixity
    return fixity

