def _validate_objects(self):
    num_objects, good_objects = 0, 0
    for obj in self.storage.iter_objects():
        num_objects += 1
        if obj.is_valid():
            good_objects += 1
    return num_objects, good_objects

def _validate_digests(self):
    num_digests, good_digests = 0, 0
    for digest in self.storage.iter_digests():
        num_digests += 1
        if digest.is_valid():
            good_digests += 1
    return num_digests, good_digests
