def parse_arguments(*unparsed_arguments):
    """
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    """
    parser = argparse.ArgumentParser()
    subparsers = parser.add_subparsers(dest="subparser")
    # Add global arguments
    for attribute in ["help", "version", "os_families"]:
        subparsers.add_parser("global", help=f"Command-line arguments and their descriptions")
    for command in commands:
        parser = subparsers.add_parser(command.name, help=command.description)
        for parameter in command.parameters:
            if parameter.subparser:
                sub_parser = parser.add_subparsers(dest=parameter.dest)
                for sub_command in command.sub_commands:
                    sub_parser.add_parser(sub_command.name, help=sub_command.description)
                    for sub_parameter in sub_command.parameters:
                        if sub_parameter.boolean:
                            sub_parser.add_argument(sub_parameter.name, action="store_true")
                        else:
                            sub_parser.add_argument(sub_parameter.name, type=sub_parameter.dtype, default=sub_parameter.default)
            else:
                if parameter.boolean:
                    parser.add_argument(parameter.name, action="store_true")
                else:
                    parser.add_argument(parameter.name, type=parameter.dtype, default=parameter.default)
    args = parser.parse_args()
    return {
        "global": args,
        command.name: args for command in commands,
        sub_command.name: args for sub_command in sub_commands,
    }
