def split(s, platform=None):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform:
    This = auto from current platform;
    1=POSIX;
    0=Windows/CMD
    Other values reserved)
    """
    if platform not in ['this', '1', '0']:
        raise ValueError("Invalid platform: {}".format(platform))

    if platform == 'this':
        if ((sys.platform =='win32') or (sys.platform=='cygwin') or (os.name == 'nt')):
            platform = 0
        else:
            platform = 1

    # Use platform-specific split regex
    split_regex = {
        1: _posix_split_re,
        0: _windows_split_re
    }[platform]

    return re.split(split_regex, s)

