                configuration_files[config_filename] = json.load(file)
                file.close()
        except json.JSONDecodeError as err:
            parse_errors.append(logging.LogRecord(
                name=__name__, level=logging.ERROR, pathname=config_filename, lineno=err.lineno,
                msg=f"Parse error in {config_filename}: {err.msg}"
            ))

    if resolve_env:
        for filename, config in configuration_files.items():
            for key, value in config.items():
                if isinstance(value, str) and value.startswith('$'):
                    try:
                        config[key] = os.environ[value[1:]]
                    except KeyError:
                        parse_errors.append(logging.LogRecord(
                            name=__name__, level=logging.ERROR, pathname=filename, lineno=None,
                            msg=f"No environment variable defined for {value}"
