def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    tags = set()
    tag_start = False
    in_code_block = False
    replaced_text = ""

    for char in text:
        if char == "<":
            tag_start = True
        elif char == ">":
            tag_start = False

        if tag_start:
            tags.add(char)
        elif char == "```" and not in_code_block:
            in_code_block = True
        elif char == "```" and in_code_block:
            in_code_block = False

        if replacer:
            if tag_start:
                tag = char
            else:
                tag = ""
            replaced_text += replacer(tag)
        else:
            replaced_text += char

    return tags, replaced_text

