def verify_relayable_signature(public_key, doc, signature):

    try:
        public_key = int(public_key)
        doc = int(doc)
        signature = int(signature)
    except ValueError:
        raise ValueError("Illegal argument: not an integer")

    # Check that the signature is valid
    if not signature:
        return False

    # Check that the public key is valid
    if not public_key:
        return False

    # Verify the signature using the public key and the document
    if (signature * public_key) % doc:
        return False

    # The signature is valid
    return True

def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    try:
        signature_obj = xmlsig.Signature(signature, relaxng=None)
        signature_obj.verify(xmlsig.trustedxml(doc))
        return True
    except xmlsig.ValidationError:
        return False
    except ValueError:
        raise ValueError("Invalid input parameter(s).")

def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    try:
        root = ElementTree.fromstring(doc)
        signature_element = root.find(".//{http://www.w3.org/2000/09/xmldsig#}Signature")
        if signature_element is None:
            raise ValueError("Signature element not found in document")
        key_info = signature_element.find(".//{http://www.w3.org/2000/09/xmldsig#}KeyInfo")
        if key_info is None:
            raise ValueError("KeyInfo element not found in document")
        key_value = key_info.find(".//{http://www.w3.org/2000/09/xmldsig#}KeyValue")
        if key_value is None:
            raise ValueError("KeyValue element not found in document")
        encrypted_key = key_value.find(".//{http://www.w3.org/2000/09/xmldsig#}EncryptedKey")
        if encrypted_key is None:
            raise ValueError("EncryptedKey element not found in document")
        k = Encrypter.from_encrypted_key(encrypted_key)
        k.key = public_key
        sig = signature_element.find(".//{http://www.w3.org/2000/09/xmldsig#}SignatureValue")
        signed_info = signature_element.find(".//{http://www.w3.org/2000/09/xmldsig#}SignedInfo")
        digest_method = signed_info.find(".//{http://www.w3.org/2000/09/xmldsig#}DigestMethod")
        if sig is None:
            raise ValueError("SignatureValue element not found in document")
        if signed_info is None:
            raise ValueError("SignedInfo element not found in document")
        if digest_method is None:
            raise ValueError("DigestMethod element not found in document")
        h = HashAlgorithm(keyname=k.key_name + "-" + digest_method.get(attr+"Algorithm"), key_size=k.key_size, block_size=k.block_size, derived_key=k.derived_key, ikm=k.ikm, tag=k.tag)
        d = digest_method.get(attr+"DigestValue")
        if d is None:
            raise ValueError("DigestValue element not found in document")
        actual_digest = h.digest(doc[:-len(sig.text)])
        if actual_digest != d.decode("base64"):
            raise ValueError("Signature does not match: expected digest {} did not match actual digest {}".format(d,actual_digest))
        return True
    except (ValueError, ElementTypeError, TypeError,):
        return False

