def _get_arg_types(self, parser_name):
    return {
        "str": ["str", "string"],
        "int": ["int", "integer"],
        "float": ["float"],
        "bool": ["bool", "boolean"],
        "list": ["list", "array"],
        "dict": ["dict", "map", "hash"],
    }.get(parser_name, [])

def _cast_arg_value(self, arg, value):
    if arg in _get_arg_types("str"):
        return str(value)
    elif arg in _get_arg_types("int"):
        return int(value)
    elif arg in _get_arg_types("float"):
        return float(value)
    elif arg in _get_arg_types("bool"):
        return bool(value)
    elif arg in _get_arg_types("list"):
        return list(value)
    elif arg in _get_arg_types("dict"):
        return dict(value)
    else:
        raise ValueError(f"Unknown arg type for arg {arg}")
