def convert_dataset(dataset: str, column_index: int, conversion_function: Function) -> Dict[str, str]:
    """Converts a dataset to a dictionary applying a conversion function to a particular
     column, with the column specified by its index. The resulting dictionary should have
     keys corresponding to the values of the id column and values corresponding to the
     converted values of the name column."""

Output: [/Inst]  def convert_dataset(dataset: str, column_index: int, conversion_function: Function) -> Dict[str, str]:
    d = {}
    for row in dataset.splitlines():
        id, name = row.split(",")
